// navigation
function GlobalNav() {
	const body = document.getElementsByTagName("body")[0];
	const gh = document.getElementById("Gh");
	const overlay = document.querySelector(".overlay_bk");

	function drawerMenu() {
		const btn = document.querySelector(".menu__button");
		const anm = document.querySelectorAll(".anm");
		let time = 0.1;
		let delay = 0.05;

		function onClick() {
			if (gh.classList.contains("-show")) {
				gh.classList.remove("-show");
				gh.classList.add("-hide");

				for (let i = 0; i < anm.length; i++) {
					anm[i].style.transitionDelay = "0s";
				}

			} else {
				gh.classList.remove("-hide");
				gh.classList.add("-show");

				for (let i = 0; i < anm.length; i++) {
					anm[i].style.transitionDelay = time + (delay * i) + "s";
				}
			}
		}
		btn.addEventListener("click", onClick, false);
	}
	drawerMenu();

	overlay.addEventListener("click", function(){
		if (gh.classList.contains("-show")) {
			gh.classList.remove("-show");
		}
	}, false);

	// Menü nach Klick auf einen Menüpunkt schließen, damit es beim
	// Scrollen zur Zielsektion nicht geöffnet stehen bleibt.
	const navLinks = document.querySelectorAll(".g-nav__anchor");
	for (let i = 0; i < navLinks.length; i++) {
		navLinks[i].addEventListener("click", function() {
			if (gh.classList.contains("-show")) {
				gh.classList.remove("-show");
				gh.classList.add("-hide");
			}
		}, false);
	}
}




const ChangeWindowSize = function() {
	const b = document.getElementsByTagName('body')[0];
	const mediaQuery = window.matchMedia('(min-width: 1280px)');

	function resize(e) {
		if (e.matches) {
			b.classList.remove('sp');
			b.classList.add('pc');

		} else {
			b.classList.remove('pc');
			b.classList.add('sp');
		}
	}

	resize(mediaQuery);
	mediaQuery.addEventListener('change', resize, false);
};



// ページ内スクロール / https://flex-box.net/js-smoothscroll/
function smoothscroll() {
	const scrollTrigger = document.querySelectorAll('a[href^="#"]');
	
	for (let i = 0; i < scrollTrigger.length; i++) {
		scrollTrigger[i].addEventListener ("click", function(e) {
			e.preventDefault();
			let href = scrollTrigger[i].getAttribute("href");
			let targetElement = document.getElementById(href.replace('#', ''));
			const rect = targetElement.getBoundingClientRect().top;
			const offset = window.pageYOffset;
			const gap = 100;
			const target = rect + offset - gap;

			window.scrollTo({
				top: target,
				behavior: 'smooth',
			});
		});
	}
};




document.addEventListener("DOMContentLoaded", function() {
	const b = document.getElementsByTagName("body")[0];
	
	if (!TEST_MODE) {
		Icon.set();
	}
	
	b.classList.add("domContentLoaded");

	//MAIN.init();
	GlobalNav();
	ChangeWindowSize();
	smoothscroll();
});

window.addEventListener("load", function() {
	var b = document.getElementsByTagName("body")[0];
	b.classList.add("onload");
}, false);





